--
-- Table structure for table `episode_points_official`
--

CREATE TABLE `episode_points_official` (
  `id` mediumint(7) UNSIGNED NOT NULL COMMENT 'Unique identifier',
  `show_id` tinyint(2) UNSIGNED DEFAULT NULL COMMENT 'Show ID',
  `season_id` smallint(3) UNSIGNED DEFAULT NULL COMMENT 'Season ID',
  `episode_id` smallint(4) UNSIGNED DEFAULT NULL COMMENT 'Episode ID',
  `contestant_id` smallint(4) UNSIGNED DEFAULT NULL COMMENT 'Contestant ID',
  `guest_contestant` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Were they a guest contestant?',
  `total_points` decimal(4,1) DEFAULT NULL COMMENT 'Total points'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

